\begin{equation}
\Delta\mu_{2}=\left(\mu_{\mathrm{M o S}_{2}}+\mu_{\mathrm{W T e}_{2}}\right)-\left(\mu_{\mathrm{M o T e}_{2}}+\mu_{\mathrm{W S}_{2}}\right)
\end{equation}

