\begin{equation}
\Delta\mu_{3}=\left(\mu_{\mathrm{M o S e}_{2}}+\mu_{\mathrm{W T e}_{2}}\right)-\left(\mu_{\mathrm{M o T e}_{2}}+\mu_{\mathrm{W S e}_{2}}\right)
